import{_ as n,h as i,i as e,c as h,v as t,p as l,x as r,m as o,e as s,S as d}from"./chunks/framework.Dvtg8yj2.js";const E=JSON.parse('{"title":"端侧上下文与 KV 预算","description":"","frontmatter":{"title":"端侧上下文与 KV 预算","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/on-device-kv.md","filePath":"llm/on-device-kv.md","lastUpdated":1788454257000}'),p={name:"llm/on-device-kv.md"};function _(c,a,k,K,A,V){const m=i("Mermaid");return e(),h("div",null,[a[1]||(a[1]=t('<h1 id="端侧上下文与-kv-预算" tabindex="-1">端侧上下文与 KV 预算 <a class="header-anchor" href="#端侧上下文与-kv-预算" aria-label="Permalink to &quot;端侧上下文与 KV 预算&quot;">​</a></h1><div class="epigraph"><p>端侧能接住多长的对话，先看你愿为过去每一个标记留下多少字节的键值；公式比「支持 128K」的营销句更早给出否决。</p><footer>—— 把服务端 KV 预算搬到内存以百 MB 计的设备上</footer></div><p>云端讨论长上下文，显存以数十 GB 计，瓶颈往往是带宽与核。手机、NPU 棒、嵌入式板上，DRAM 与可长期占用的工作区常常只有几百 MB 分给模型。权重已经占掉一截，剩下的要同时容纳激活、KV 缓存、操作系统与 UI。这时上下文长度不是模型卡上的位置编码上限，而是一条字节不等式。本篇把端侧上下文写成 <strong>KV 预算</strong>，公式与服务端相同，只是右边的 \\(B\\) 小了两个数量级。注意力二次代价见 <a href="/llm/attention-quadratic-cost">二次复杂度</a>，压缩手段见 <a href="/llm/kv-as-long-context">KV 作为长上下文</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归解码每步都要读历史键值。满缓存的体积由六个数相乘：</p> \\[\\mathrm{bytes} = L \\times n \\times h_{\\mathrm{kv}} \\times d \\times 2 \\times b \\]<p>\\(L\\) 是层数，\\(n\\) 是当前序列长度（提示加已生成），\\(h_{\\mathrm{kv}}\\) 是 KV 头数，\\(d\\) 是头维，\\(2\\) 表示键与值各一份，\\(b\\) 是每个元素的字节数（FP16 为 2，INT8 为 1，INT4 为 0.5）。查询头数不出现在式中：GQA 省缓存，靠的是减 \\(h_{\\mathrm{kv}}\\)，不是减 \\(h_q\\)。</p><p>端侧的问题是 \\(B_{\\mathrm{kv}}\\) 往往先于算力见顶。一个 3B 级、32 层、8 个 KV 头、\\(d=128\\) 的模型，在 FP16、\\(n=4096\\) 时：</p> \\[32 \\times 4096 \\times 8 \\times 128 \\times 2 \\times 2 = 512\\,\\mathrm{MiB}. \\]<p>半 GB 只是 KV，尚未计权重。许多「端侧 7B」方案在 4-bit 权重下勉强塞进 4GB 机，KV 再按 4K 满精度去留，会话一长就与系统抢内存，被杀或被切到 CPU。</p><h3 id="营销长度与驻留长度" tabindex="-1">营销长度与驻留长度 <a class="header-anchor" href="#营销长度与驻留长度" aria-label="Permalink to &quot;营销长度与驻留长度&quot;">​</a></h3><p>位置编码或微调声称的 32K、128K，是<strong>几何上还能编号</strong>的长度。驻留长度是 \\(n_{\\mathrm{keep}}\\)，满足 \\(L n_{\\mathrm{keep}} h_{\\mathrm{kv}} d \\cdot 2 b \\le B_{\\mathrm{kv}}\\)。两者经常差一个数量级。针测 32K 而设备只留得下 2K 缓存，测的是实验室，不是产品。滑窗、量化、逐出，都是在改 \\(n_{\\mathrm{keep}}\\)、\\(b\\) 或 \\(h_{\\mathrm{kv}}\\)，好让不等式成立。</p><p><span class="marginnote">公式里的 \\(d\\) 是每个 KV 头的通道数，不是模型嵌入宽。嵌入宽 \\(d_{\\mathrm{model}}=h_q\\cdot d\\)。写错这一项会把预算高估或低估 \\(h_q\\) 倍。MLA 一类潜向量压缩则把 \\(d\\) 换成更窄的 \\(d_c\\)，不能继续套本式的满头宽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先定 \\(B_{\\mathrm{kv}}\\)，再反解允许的 \\(n\\)。把权重、KV、激活峰值写成三笔互斥预算，避免「模型能加载」被当成「对话能变长」。常见操作按改哪个因子分类。</p><p>减 \\(h_{\\mathrm{kv}}\\)：<a href="/llm/gqa">GQA</a> / <a href="/llm/mqa">MQA</a>。从 32 头 KV 降到 8 头或 1 头，字节线性降。质量有代价，但对端侧几乎是必选项。Grok-1 公开的 48 查询 / 8 KV 是云端同款思路，只是它的 \\(L\\) 与 \\(d_{\\mathrm{model}}\\) 对端侧仍不可承受。</p><p>减 \\(b\\)：KV 量化到 INT8 或 4-bit。权重量化省的是静态体积，KV 量化省的是随 \\(n\\) 涨的那一截。端侧校准数据少，KV 量化比权重量化更容易在长对话后半段失真。</p><p>减 \\(n_{\\mathrm{keep}}\\)：滑动窗口、注意力汇、H2O / SnapKV 一类逐出。窗口 \\(w=1024\\) 时，上式的 \\(n\\) 换成 \\(w\\)（外加少量汇 token）。有效上下文变成「最近 \\(w\\) 加少量锚」，不是训练时的 \\(n_{\\max}\\)。</p>',18)),(e(),l(d,null,{default:r(()=>[s(m,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E8%AE%BE%E5%A4%87%E5%88%86%E7%BB%99%20KV%20%E7%9A%84%E5%AD%97%E8%8A%82%20B%22%5D%20--%3E%20EQ%5B%22L%20%C3%97%20n%20%C3%97%20h_kv%20%C3%97%20d%20%C3%97%202%20%C3%97%20b%20%E2%89%A4%20B%22%5D%0A%20%20EQ%20--%3E%20N%5B%22%E5%8F%8D%E8%A7%A3%E5%85%81%E8%AE%B8%E7%9A%84%20n%22%5D%0A%20%20N%20--%3E%20HQ%5B%22%E5%87%8F%20KV%20%E5%A4%B4%EF%BC%9AGQA%20%2F%20MQA%22%5D%0A%20%20N%20--%3E%20Q%5B%22%E5%87%8F%20dtype%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20N%20--%3E%20W%5B%22%E5%87%8F%E9%A9%BB%E7%95%99%E9%95%BF%E5%BA%A6%EF%BC%9A%E7%AA%97%E5%8F%A3%20%2F%20%E9%80%90%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="会话产品要把预填充和生成拆开算" tabindex="-1">会话产品要把预填充和生成拆开算 <a class="header-anchor" href="#会话产品要把预填充和生成拆开算" aria-label="Permalink to &quot;会话产品要把预填充和生成拆开算&quot;">​</a></h3><p>预填充一次算完提示，激活峰值高、KV 一次性写成 \\(n_{\\mathrm{prompt}}\\)。生成阶段激活小，但每步扫全部 KV，带宽墙。端侧 NPU 往往对动态 \\(n\\) 不友好：每次增长都可能触发重编译或低效的动态轴。工程上常用的是<strong>固定槽位</strong>：预分配 \\(n_{\\mathrm{max}}\\) 的 KV，提示短就 padding 或留下空槽，生成触及上限再窗口滑动。槽位按 16/32 对齐，既满足 <a href="/llm/npu-friendly-ops">NPU 友好算子</a>，又让 \\(B_{\\mathrm{kv}}\\) 是编译期常数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为何字节公式如此硬：decode 不重算历史值向量，必须把它们放在可寻址存储里。层与层不共享 KV（除非刻意跨层共享，那是另一种方法），所以乘 \\(L\\)。每头一套键值几何，所以乘 \\(h_{\\mathrm{kv}}\\)。键和值同等驻留，所以乘 2。没有任何一项能被「模型很小」自动消掉：1B 与 7B 若 \\(L\\)、\\(h_{\\mathrm{kv}}\\)、\\(d\\) 同构，KV 一样大；小的是权重，不是缓存。这解释了为何端侧 1B 有时仍不敢开 8K——不是权重放不下，是 32 层缓存放不下。</p><p>二次注意力的计算量是 \\(O(n^2 d)\\) 量级，端侧预填充在 \\(n\\) 到几千时可能已经比 decode 更痛。窗口把预填充也切成局部，计算与存储一起降。代价是文档前部的事实退出驻留，必须靠摘要、检索或用户界面把关键句重新放进窗口。</p><p><span class="marginnote">同一条公式在云端用来定并发：batch 再乘一个因子。端侧 batch 几乎总是 1，省下的并发预算应还给 \\(n\\) 或留给 UI，而不是幻想「手机上也能 batch 8」。</span></p><h3 id="精度与头数哪一个先砍" tabindex="-1">精度与头数哪一个先砍 <a class="header-anchor" href="#精度与头数哪一个先砍" aria-label="Permalink to &quot;精度与头数哪一个先砍&quot;">​</a></h3><p>在固定 \\(B_{\\mathrm{kv}}\\) 下，\\(b\\) 减半与 \\(h_{\\mathrm{kv}}\\) 减半等价于同一字节。质量失败模式不同：量化是噪声，减头是结构共享。经验上先上 GQA 再上 KV INT8，比先把满头 MHA 打到 4-bit 更稳，因为端侧 4-bit KV 在长会话后半段容易把注意力熵搅乱。具体顺序仍要在目标芯片上测，公式只保证字节，不保证分数。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>公式假设每层每 token 满额驻留。共享 KV 跨层、MLA、线性注意力、无 KV 的 RNN/SSM 混合，会改公式，不能硬套。声称「端侧 128K」时，应同时公开 \\(L,h_{\\mathrm{kv}},d,b,n_{\\mathrm{keep}}\\)。缺一项，数字不可信。</p><p>多轮对话里 \\(n\\) 是累计的：系统提示、历史轮次、本轮用户话、已生成回复，全部计进同一条缓存。只按「本轮用户说了多少字」去估预算，会在第三轮才发现已经撞上 \\(B_{\\mathrm{kv}}\\)。产品侧通常要在槽满时折叠历史（摘要进系统段、丢掉最早轮、或滑窗），折叠等于改 \\(n_{\\mathrm{keep}}\\) 的内容而不是改公式。</p><p>SLM 的能力悬崖与 KV 悬崖叠加：小模型本就不利于长依赖，再把 \\(n_{\\mathrm{keep}}\\) 砍到 1K，产品表现会同时像「模型笨」和「记性差」。诊断时应先打印实际驻留长度，再谈蒸馏数据。操作系统杀进程、热节流降频，会在公式之外再砍有效吞吐；预算表要按最坏内存水位留余量，而不是按空载实验室。</p><p><span class="marginnote">dtype 的 \\(b\\) 对 KV 与权重可以不同。权重 4-bit、KV FP16 是常见组合：权重量一次，KV 每步都在累计量化误差。反向组合（权重 FP16、KV 4-bit）较少见，因为权重体积通常先爆。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端侧上下文首先是 KV 字节预算：\\(\\mathrm{bytes}=L\\times n\\times h_{\\mathrm{kv}}\\times d\\times 2\\times b\\)。</li><li>模型卡上的最大长度是编号能力；产品长度是满足不等式的 \\(n_{\\mathrm{keep}}\\)。</li><li>调节因子是头数、元素宽度、驻留条数；查询头数不进缓存公式。</li><li>端侧常预分配固定槽并对齐，以避免动态 \\(n\\) 与 NPU 冲突。</li><li>小权重不等于小 KV：同构的层与头，1B 与 7B 缓存同级。</li><li>出处：缓存体积是 Transformer 解码的直接推论；头数权衡见 Shazeer（2019）与 Ainslie 等 GQA（2023）。不编造端侧评测论文编号。</li></ul>',15))])}const b=n(p,[["render",_]]);export{E as __pageData,b as default};
